import base64,hashlib,json,os,pathlib
os.umask(0o077)
out=pathlib.Path('/home/qian-qi/heptabao-kv2-ha-convergence-20261106-r1/build-test-ci422-9c68-r12')
out.mkdir(mode=0o700)
items=[{"name":"controller.py","bytes":29547,"sha256":"0d87410a2f73fced9dc7311e882bb68de020e7c7fb2ee2581d34a9e1303f2479","base64":""},{"name":"test-selection.public.json","bytes":18971,"sha256":"ad7642bab8218200941ccb09675934b222189c47f6f740708566b19a8f7c57c9","base64":""},{"name":"candidate.bundle","bytes":3383,"sha256":"9e0dcb3676ad12f7a91235769963e34d7c7159906dcda1b129b20e58b95a7ab7","base64":""}]
for item in items:
 b=base64.b64decode(item['base64'],validate=True)
 assert len(b)==item['bytes'] and hashlib.sha256(b).hexdigest()==item['sha256']
 with (out/item['name']).open('xb') as f:
  f.write(b);f.flush();os.fsync(f.fileno())
assert (out/'candidate.bundle').is_file()
print(json.dumps({'event':'controller_installed','controller_sha256':items[0]['sha256'],'selection_sha256':items[1]['sha256'],'bundle_sha256':items[2]['sha256']}),flush=True)
os.execv('/usr/bin/python3',['/usr/bin/python3',str(out/'controller.py')])
